#!/usr/bin/env bash
set -euo pipefail

usage() {
  cat <<'USAGE'
Usage:
  tool/l10n.sh package <package-path>
  tool/l10n.sh all
  tool/l10n.sh check
USAGE
}

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$repo_root"

mode="${1:-}"

gen_l10n() {
  local path="$1"
  if [[ ! -f "$path/l10n.yaml" ]]; then
    echo "No l10n.yaml at $path" >&2
    exit 1
  fi
  echo "==> gen-l10n $path"
  (cd "$path" && flutter gen-l10n)
}

all_l10n_paths() {
  find apps packages -name l10n.yaml -print | sed 's#/l10n.yaml$##' | sort
}

case "$mode" in
  package)
    path="${2:-}"
    [[ -n "$path" ]] || { usage; exit 1; }
    gen_l10n "$path"
    ;;
  all)
    paths_file="$(mktemp)"
    trap 'rm -f "$paths_file"' EXIT
    all_l10n_paths >"$paths_file"
    paths=()
    while IFS= read -r path; do
      [[ -n "$path" ]] && paths[${#paths[@]}]="$path"
    done <"$paths_file"
    rm -f "$paths_file"
    trap - EXIT
    if [[ "${#paths[@]}" -eq 0 ]]; then
      echo "No l10n.yaml files found."
      exit 0
    fi
    for path in "${paths[@]}"; do
      gen_l10n "$path"
    done
    ;;
  check)
    before_file="$(mktemp)"
    after_file="$(mktemp)"
    trap 'rm -f "$before_file" "$after_file"' EXIT
    git diff -- apps packages >"$before_file"
    "$0" all
    git diff -- apps packages >"$after_file"
    if ! cmp -s "$before_file" "$after_file"; then
      echo "Generated localization output changed." >&2
      git diff -- apps packages
      exit 1
    fi
    rm -f "$before_file" "$after_file"
    trap - EXIT
    ;;
  *)
    usage
    exit 1
    ;;
